export function Skills() {
  const containerVariants = {
    hidden: {
      opacity: 0
    },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.06
      }
    }
  };
  const itemVariants = {
    hidden: {
      opacity: 0,
      scale: 0.9
    },
    visible: {
      opacity: 1,
      scale: 1,
      transition: {
        duration: 0.3
      }
    }
  };
  return (
    <SectionWrapper id="skills" className="bg-white dark:bg-slate-950">
      <SectionHeader
        title="Skills & Expertise"
        subtitle="Technologies and tools I use to bring ideas to life." />
      

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 lg:gap-12">
        {skillCategories.map((category, index) =>
        <motion.div
          key={category.title}
          initial={{
            opacity: 0,
            y: 20
          }}
          whileInView={{
            opacity: 1,
            y: 0
          }}
          viewport={{
            once: true,
            margin: '-50px'
          }}
          transition={{
            duration: 0.5,
            delay: index * 0.1
          }}
          className="bg-slate-50 dark:bg-slate-900/50 rounded-2xl p-8 border border-slate-100 dark:border-slate-800/50">
          
            <div className="flex items-center gap-4 mb-6">
              <div className="p-3 rounded-xl bg-white dark:bg-slate-800 text-accent-600 dark:text-accent-400 shadow-sm">
                {category.icon}
              </div>
              <h3 className="text-xl font-heading font-bold text-slate-900 dark:text-white">
                {category.title}
              </h3>
            </div>

            <motion.div
            variants={containerVariants}
            initial="hidden"
            whileInView="visible"
            viewport={{
              once: true
            }}
            className="flex flex-wrap gap-3">
            
              {category.skills.map((skill) =>
            <motion.span
              key={skill}
              variants={itemVariants}
              className="inline-flex items-center gap-2 px-4 py-2.5 rounded-lg bg-white dark:bg-slate-800 text-sm font-medium text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 shadow-sm hover:border-accent-500 dark:hover:border-accent-500 hover:shadow-md transition-all cursor-default">
              
                  <span className="text-slate-500 dark:text-slate-400 flex-shrink-0">
                    <SkillIcon name={skill} />
                  </span>
                  {skill}
                </motion.span>
            )}
            </motion.div>
          </motion.div>
        )}
      </div>
    </SectionWrapper>);

}
